-- Change-history check at all nearest archive slots projected from 421 off-grid source rows.
-- READ-ONLY only; source timestamp history and projected target history are distinct.
WITH source_rows AS (SELECT w.dateTime,FLOOR((w.dateTime+150)/300)*300 AS nearest_300 FROM weewx_WH1080.archive w LEFT JOIN loucka_reconstruction.archive a ON a.dateTime=w.dateTime WHERE w.dateTime>=1522540800 AND w.dateTime<1546300800 AND w.usUnits=17 AND a.dateTime IS NULL), target_keys AS (SELECT DISTINCT nearest_300 FROM source_rows) SELECT c.target_time,c.variable,c.batch_key,c.old_value,c.new_value,c.source_database,c.source_time,c.source_value,c.reason,c.state,c.created_at,c.applied_at FROM target_keys k JOIN loucka_reconstruction.reconstruction_changes c ON c.target_time=k.nearest_300 ORDER BY c.target_time,c.variable,c.id;
